     * - [`AnalysisError::EmptyRange`] if the window selects no finite samples.
     * - [`AnalysisError::WindowOutOfBounds`] for an inverted window.
     */
    func channelStats(channel: String, window: FfiWindow) throws  -> StatsDto
    
    /**
